"""Private reference review; only the report is written to the agent workspace."""
import json
import os
from pathlib import Path

REPO = Path(os.environ.get("BENCH_REPO_ROOT", "/app/repo"))
APP = Path(os.environ.get("BENCH_APP_ROOT", "/app"))
REPORT = json.loads("{\"schema_version\":2,\"reviews\":[{\"candidate\":\"cedar\",\"decision\":\"reject\",\"location\":{\"path\":\"candidates/cedar/clip.py\",\"line\":2},\"behavior\":\"The candidate violates the documented public behavior on the supplied executable counterexample.\",\"cases\":[{\"input\":{\"values\":[-3,2,19],\"lo\":0,\"hi\":10},\"expected\":{\"values\":[0,2,10],\"original\":[-3,2,19]}},{\"input\":{\"values\":[0,10],\"lo\":0,\"hi\":10},\"expected\":{\"values\":[0,10],\"original\":[0,10]}},{\"input\":{\"values\":[-2.5,0.5],\"lo\":-2,\"hi\":-1},\"expected\":{\"values\":[-2,-1],\"original\":[-2.5,0.5]}},{\"input\":{\"values\":[],\"lo\":4,\"hi\":1},\"expected\":{\"error\":\"ValueError\"}},{\"input\":{\"values\":[5],\"lo\":5,\"hi\":5},\"expected\":{\"values\":[5],\"original\":[5]}},{\"input\":{\"values\":[],\"lo\":0,\"hi\":1},\"expected\":{\"values\":[],\"original\":[]}}]},{\"candidate\":\"maple\",\"decision\":\"accept\",\"location\":null,\"behavior\":null,\"cases\":[{\"input\":{\"values\":[-3,2,19],\"lo\":0,\"hi\":10},\"expected\":{\"values\":[0,2,10],\"original\":[-3,2,19]}},{\"input\":{\"values\":[0,10],\"lo\":0,\"hi\":10},\"expected\":{\"values\":[0,10],\"original\":[0,10]}},{\"input\":{\"values\":[-2.5,0.5],\"lo\":-2,\"hi\":-1},\"expected\":{\"values\":[-2,-1],\"original\":[-2.5,0.5]}},{\"input\":{\"values\":[],\"lo\":4,\"hi\":1},\"expected\":{\"error\":\"ValueError\"}},{\"input\":{\"values\":[5],\"lo\":5,\"hi\":5},\"expected\":{\"values\":[5],\"original\":[5]}},{\"input\":{\"values\":[],\"lo\":0,\"hi\":1},\"expected\":{\"values\":[],\"original\":[]}}]},{\"candidate\":\"birch\",\"decision\":\"reject\",\"location\":{\"path\":\"candidates/birch/clip.py\",\"line\":4},\"behavior\":\"The candidate violates the documented public behavior on the supplied executable counterexample.\",\"cases\":[{\"input\":{\"values\":[-3,2,19],\"lo\":0,\"hi\":10},\"expected\":{\"values\":[0,2,10],\"original\":[-3,2,19]}},{\"input\":{\"values\":[0,10],\"lo\":0,\"hi\":10},\"expected\":{\"values\":[0,10],\"original\":[0,10]}},{\"input\":{\"values\":[-2.5,0.5],\"lo\":-2,\"hi\":-1},\"expected\":{\"values\":[-2,-1],\"original\":[-2.5,0.5]}},{\"input\":{\"values\":[],\"lo\":4,\"hi\":1},\"expected\":{\"error\":\"ValueError\"}},{\"input\":{\"values\":[5],\"lo\":5,\"hi\":5},\"expected\":{\"values\":[5],\"original\":[5]}},{\"input\":{\"values\":[],\"lo\":0,\"hi\":1},\"expected\":{\"values\":[],\"original\":[]}}]},{\"candidate\":\"willow\",\"decision\":\"accept\",\"location\":null,\"behavior\":null,\"cases\":[{\"input\":{\"values\":[-3,2,19],\"lo\":0,\"hi\":10},\"expected\":{\"values\":[0,2,10],\"original\":[-3,2,19]}},{\"input\":{\"values\":[0,10],\"lo\":0,\"hi\":10},\"expected\":{\"values\":[0,10],\"original\":[0,10]}},{\"input\":{\"values\":[-2.5,0.5],\"lo\":-2,\"hi\":-1},\"expected\":{\"values\":[-2,-1],\"original\":[-2.5,0.5]}},{\"input\":{\"values\":[],\"lo\":4,\"hi\":1},\"expected\":{\"error\":\"ValueError\"}},{\"input\":{\"values\":[5],\"lo\":5,\"hi\":5},\"expected\":{\"values\":[5],\"original\":[5]}},{\"input\":{\"values\":[],\"lo\":0,\"hi\":1},\"expected\":{\"values\":[],\"original\":[]}}]}]}")

def main():
    candidates = json.loads((REPO / "candidates.json").read_text())["candidates"]
    assert set(candidates) == {row["candidate"] for row in REPORT["reviews"]}
    APP.mkdir(parents=True, exist_ok=True)
    (APP / "review.json").write_text(json.dumps(REPORT, ensure_ascii=False, allow_nan=False, indent=2) + "\n", encoding="utf-8")

if __name__ == "__main__":
    main()

